export const dimensions = ['内容与任务','结构与连贯','表达与细节','词汇运用','语法与规范'];
export const rules = [
  {id:'R01',title:'内容与任务完成',text:'围绕题目呈现具体事件，说明变化及其原因。内容判断应引用原文。',weight:30},
  {id:'R02',title:'结构与连贯',text:'检查段落顺序、过渡和首尾照应；不能只把段落分数平均。',weight:25},
  {id:'R03',title:'表达与细节',text:'鼓励动作、对话与感受的具体描写，不用固定句式替代学生声音。',weight:20},
  {id:'R04',title:'词汇运用',text:'结合语境检查词汇准确性；专名、引语及允许的语言切换不直接扣分。',weight:15},
  {id:'R05',title:'语法与规范',text:'只评确认后的文字。方言须按任务政策处理，识别错误与真实错字分开。',weight:10},
];
export const samples = {
  zh:{title:'一次小小的改变',language:'中文',policy:'zh',rubric:'七年级 · 叙事文 v0.1',weights:[30,25,20,15,10],scores:[25,20,16,12,8],text:'以前，我总觉得教室里的那盆绿萝与我无关。每天放学，我背起书包就走，从没有留意过它垂下的叶子。\n\n一个星期五，我最后离开教室。夕阳照在窗台上，绿萝的叶尖已经发黄。我停下脚步，拿起自己的水杯，把剩下的水慢慢倒进花盆。泥土吸水时发出轻轻的声音，像一句小小的谢谢。\n\n从那以后，我每天都来给它浇水。过了几天，叶子又抬起了头。同桌发现了我的秘密，也加入进来。后来我们做了一张值日表，提醒大家照顾它。\n\n我明白了一个道理：改变不一定是一件大事。只要愿意停下脚步，一杯水也能让教室变得不一样。',summary:'从一杯水写起，变化真实而清楚。',feedback:[{type:'strength',title:'小事切入，主题清楚',quote:'一杯水也能让教室变得不一样。',body:'结尾回到了浇水这件小事，让“改变”的主题具体可感。',rule:'R01'}, {type:'strength',title:'有画面感的细节',quote:'泥土吸水时发出轻轻的声音',body:'声音细节让读者感受到“我”开始认真观察身边的事物。',rule:'R03'}, {type:'improve',title:'把转变过程再写具体一点',quote:'同桌发现了我的秘密，也加入进来。',body:'可以补充同桌发现时的一句话或一个动作，让一个人的改变如何影响别人更清楚。',rule:'R02'}]},
  mixed:{title:'A greener school',language:'中英混写',policy:'mixed',rubric:'八年级 · 双语表达 v0.1',weights:[25,20,15,20,20],scores:[21,16,12,16,15],text:'Our school started a green week. 我们小组决定从午餐后的垃圾分类做起。At first, some students did not know which bin to use.\n\n我和同桌画了三张小海报，把常见的垃圾画在上面。We put them next to the bins. The next day, more students stopped to read our signs.\n\n这件事让我懂得，环保不是一句口号。Small actions can make a big difference. Next week, we will ask other classes to join us.',summary:'两种语言共同讲述了一次校园行动。',feedback:[{type:'strength',title:'语言切换服务于表达',quote:'我们小组决定从午餐后的垃圾分类做起。',body:'本案例允许中英切换，中文叙述不被直接计为英语语法错误。',rule:'R04'},{type:'improve',title:'增加可观察的结果',quote:'more students stopped to read our signs.',body:'可以写一次具体的正确分类行为，说明海报产生了什么变化。',rule:'R03'}]},
  en:{title:'My weekend',language:'英语',policy:'en',rubric:'七年级 · 英语短文 v0.1',weights:[25,20,15,20,20],scores:[21,16,11,15,12],text:'Last Saturday, I go to the park with my sister. The weather was sunny and warm. We brought a ball and some sandwiches.\n\nWe played under a big tree. Then we saw a little boy looking for his kite. My sister helped him find it behind a bench. He said thank you and smiled.\n\nI was tired but happy. I learned that helping someone can make an ordinary day special.',summary:'事件完整，时态一致性值得再检查。',feedback:[{type:'strength',title:'用经历表达感受',quote:'helping someone can make an ordinary day special.',body:'结尾从帮助别人的经历中提炼感受，与前面的事件有关联。',rule:'R01'},{type:'improve',title:'过去发生的动作注意时态',quote:'Last Saturday, I go to the park',body:'这里讲述上周六发生的事，可将 go 改为 went。先想一想文章中还有哪些动作发生在过去。',rule:'R05'}]},
  dialect:{title:'外婆的厨房',language:'中文 · 方言表达',policy:'dialect',rubric:'方言表达 · 待教师选定量规',weights:[30,25,20,15,10],scores:null,text:'外婆总说：“侬慢慢吃，勿要急。”小时候，我听见这句话就知道，热腾腾的饭已经摆上桌了。\n\n厨房不大，窗边放着一盆葱。外婆切菜的时候，我坐在门口看蒸汽从锅边冒出来。那些我在课本里找不到的词，一句一句，装着家的味道。\n\n现在我到了外地上学，最想念的不是哪一道菜，而是外婆叫我吃饭的声音。',summary:'保留人物语言，交由教师确认方言量规。',feedback:[{type:'strength',title:'方言保留了人物声音',quote:'侬慢慢吃，勿要急。',body:'这是人物对话。本案例不将方言直接判为错别字；正式评分需要教师指定适用政策。',rule:'R05'},{type:'improve',title:'给不熟悉方言的读者一点线索',quote:'那些我在课本里找不到的词',body:'可结合动作或语境，让读者理解这些话表达的关心，无需全部改成普通话。',rule:'R03'}]},
};
export function codePointLength(text){return Array.from(text).length;}
export function detectLanguage(text){const zh=(text.match(/[\u3400-\u9fff]/g)||[]).length;const en=(text.match(/[a-z]/gi)||[]).length;if(zh&&en)return '中英混合（字形初筛）';if(zh)return '中文（字形初筛）';if(en)return '拉丁文字（待确认）';return '语言待确认';}
export function analyzeInput(text){const length=codePointLength(text);if(!text.trim())throw Error('请先输入作文正文。');if(length>15000)throw Error('正文超过 15,000 字符，请缩短后再评阅。');return {length,paragraphs:text.split(/\n\s*\n/).filter(p=>p.trim()).length,language:detectLanguage(text)};}
